fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let mut res = Vec::with_capacity(numbers.len() * 2 - 1);
    
    for (i, &num) in numbers.iter().enumerate() {
        if i > 0 {
            res.push(delim); // Push the delimiter before every element except the first
        }
        res.push(num); // Push the current element
    }
    
    res
}